// 3. Test Combat Actions with Health Verification (60s)
// ============================================================
cy.log("3️⃣ Testing Combat Actions with Health Verification");
// ✅ IMPROVED: Verify health changes when attacking
cy.log("Testing attack action with health tracking...");
// Capture initial health of player 2 (opponent)
cy.get('[data-testid="player2-health"]', { timeout: 5000 })
    .should("exist")
    .invoke("attr", "data-current")
    .then((health) => {
    const initialHealth = parseFloat(health);
    cy.log(`Player 2 initial health: ${initialHealth}`);
    // Execute attack
    cy.get("body").type(" ");
    // Wait for health to update using assertion instead of fixed wait
    cy.get('[data-testid="player2-health"]', { timeout: 1500 })
        .invoke("attr", "data-current")
        .should((updatedHealth) => {
        const updatedHealthValue = parseFloat(updatedHealth);
        expect(updatedHealthValue, "Opponent health should decrease after attack").to.be.lessThan(initialHealth);
    })
        .then((newHealth) => {
        const currentHealth = parseFloat(newHealth);
        cy.log(`Player 2 current health: ${currentHealth}`);
        cy.log(`✅ Damage verified: ${initialHealth - currentHealth} HP lost`);
    });
});
// Second attack with verification
cy.get('[data-testid="player2-health"]')
    .invoke("attr", "data-current")
    .then((health) => {
    const beforeAttack = parseFloat(health);
    cy.get("body").type(" ");
    // Wait for health to update using assertion
    cy.get('[data-testid="player2-health"]', { timeout: 1500 })
        .invoke("attr", "data-current")
        .should((updatedHealth) => {
        const updatedHealthValue = parseFloat(updatedHealth);
        expect(updatedHealthValue, "Second attack should deal damage").to.be.lessThan(beforeAttack);
    })
        .then((newHealth) => {
        const afterAttack = parseFloat(newHealth);
        cy.log(`✅ Second attack executed (Health: ${beforeAttack} → ${afterAttack})`);
    });
});
// Try using attack button if it exists with health verification
cy.get("body").then(($body) => {
    if ($body.find('[data-testid="attack-button"]').length > 0) {
        cy.get('[data-testid="player2-health"]')
            .invoke("attr", "data-current")
            .then((health) => {
            const before = parseFloat(health);
            cy.get('[data-testid="attack-button"]').click({ force: true });
            // Wait for health to update using assertion
            cy.get('[data-testid="player2-health"]', { timeout: 1500 })
                .invoke("attr", "data-current")
                .should((updatedHealth) => {
                const updatedHealthValue = parseFloat(updatedHealth);
                expect(updatedHealthValue, "Attack button should deal damage").to.be.lessThan(before);
            })
                .then((after) => {
                const afterValue = parseFloat(after);
                cy.log(`✅ Attack button verified (Health: ${before} → ${afterValue})`);
            });
        });
    }
    else {
        cy.log("⚠️ Attack button not found, using keyboard only");
    }
});
